// the reports in detail (1/11/2026, the same as the Hub's rotation log): a day (who reported and what), or a week/month (how many days each activity per intern)
const IXD = { p: 'd', d: '' };
function ixDetail() {
  const box = $('#ixPane'), L = ixReporters(), r = inMR(), T = IN.d.tasks || [], fd = d => dm(d);
  if (!IXD.d) IXD.d = today < r[0] ? r[0] : today > r[1] ? r[1] : today;
  if (inDow(IXD.d) > 4 && IXD.p === 'd') IXD.d = add(IXD.d, inDow(IXD.d) === 5 ? -1 : -2);
  const sun = add(IXD.d, -inDow(IXD.d)), wd = [0, 1, 2, 3, 4].map(k => add(sun, k)), rd = []; for (let d = r[0]; d <= r[1]; d = add(d, 1)) if (inDow(d) <= 4) rd.push(d);
  const span = IXD.p === 'd' ? [IXD.d] : IXD.p === 'w' ? wd : rd, ok = (i, d) => { const g = inLog(i, d); return g && g.p; };
  const lab = IXD.p === 'd' ? `יום ${DS[inDow(IXD.d)]} · ${fd(IXD.d)}` : IXD.p === 'w' ? `שבוע ${fd(wd[0])}–${fd(wd[4])}` : `סבב ${monthName(IN.m)}`;
  let body = '';
  if (IXD.p === 'd') {
    const st = i => { const k = inState(i, IXD.d), g = inLog(i, IXD.d); if (g && g.p) return '<span class="ixd-st ok">✓ דיווח/ה</span>'; return `<span class="ixd-st ${k.k}">${esc(k.k === 'wt' ? 'עד 16:00' : k.k === 'miss' ? 'חסר' : k.t || '—')}</span>`; };
    body = `<p class="cap">${L.filter(i => ok(i, IXD.d)).length}/${L.length} דיווחו · ${lab}</p><div class="ixd-w"><table class="ixd-t"><tr><th>סטאז׳ר</th><th>עמדה</th><th>מצב</th><th>מה עשה/תה</th><th>הערות</th></tr>${L.map(i => { const g = inLog(i, IXD.d), p = inPlace(i, IXD.d), tk = g && g.p ? (g.tasks || []) : [];
      return `<tr><td class="nm"><button class="nmb" data-inf="${esc(i.id)}">${inAv(i)}<b>${esc(i.name)}</b></button></td><td>${p.s ? `<span class="ixd-pl" style="--c:${p.s.color || '#5B7078'}">${esc(p.s.short || p.s.name)}</span>` : ''}</td><td>${st(i)}</td><td>${tk.length ? `<div class="ixd-ch">${tk.map(t => { const a = T.find(x => x[0] === t); return `<span>${esc(a ? a[1] : t)}</span>`; }).join('')}</div>` : ''}</td><td>${g && g.note ? `<div class="ixd-n" dir="auto">${esc(g.note)}</div>` : ''}</td></tr>`; }).join('')}</table></div>`;
  } else {
    const cnt = (i, t) => span.filter(d => { const g = inLog(i, d); return g && g.p && (g.tasks || []).indexOf(t[0]) >= 0; }).length, used = T.filter(t => L.some(i => cnt(i, t)));
    const due = span.filter(d => d <= today).length, rep = i => span.filter(d => ok(i, d)).length, mx = Math.max(1, ...L.map(i => Math.max(0, ...used.map(t => cnt(i, t)))));
    const heat = n => n ? `background:rgba(24,122,92,${(0.12 + 0.6 * n / mx).toFixed(2)});color:${n / mx > .55 ? '#fff' : '#0C2A35'}` : '';
    body = used.length ? `<p class="cap">כמה ימים סומנה כל פעילות · ${lab}</p><div class="ixd-w"><table class="ixd-t ixd-mx"><tr><th>סטאז׳ר</th><th>ימים שדווחו</th>${used.map(t => `<th class="ac">${esc(t[1])}</th>`).join('')}<th>סה״כ</th></tr>${L.map(i => { const c = used.map(t => cnt(i, t)); return `<tr><td class="nm"><button class="nmb" data-inf="${esc(i.id)}">${inAv(i)}<b>${esc(i.name)}</b></button></td><td class="c">${rep(i)}<small>/${due}</small></td>${c.map(n => `<td class="c n ${n ? '' : 'z'}" style="${heat(n)}">${n || '·'}</td>`).join('')}<td class="c n">${c.reduce((a, b) => a + b, 0)}</td></tr>`; }).join('')}<tr class="tot"><td>סה״כ</td><td class="c">${L.reduce((a, i) => a + rep(i), 0)}</td>${used.map(t => `<td class="c n">${L.reduce((a, i) => a + cnt(i, t), 0)}</td>`).join('')}<td class="c n">${L.reduce((a, i) => a + used.reduce((b, t) => b + cnt(i, t), 0), 0)}</td></tr></table></div>` : `<p class="cap">עוד אין פעילויות מדווחות ב${IXD.p === 'w' ? 'שבוע הזה' : 'סבב הזה'}</p>`;
  }
  box.innerHTML = `<div class="in-card"><div class="in-ch"><h3>📋 הדיווחים בפירוט</h3><span class="spacer"></span>${ixSeg([['d', 'יום'], ['w', 'שבוע'], ['m', 'חודש']], IXD.p, 'ixdp')}</div>${IXD.p !== 'm' ? `<div class="in-tool"><button class="btn sm" data-ixdn="-1">→</button><b class="ixd-lb">${lab}</b><button class="btn sm" data-ixdn="1">←</button><button class="btn sm" data-ixdn="0">היום</button></div>` : ''}${body}</div>`;
  box.querySelectorAll('[data-ixdp]').forEach(b => b.onclick = () => { IXD.p = b.dataset.ixdp; ixDetail(); inPhotos(); });
  box.querySelectorAll('[data-ixdn]').forEach(b => b.onclick = () => { const k = +b.dataset.ixdn; if (!k) IXD.d = ''; else if (IXD.p === 'w') IXD.d = add(IXD.d, 7 * k); else { let d = add(IXD.d, k); while (inDow(d) > 4) d = add(d, k); IXD.d = d; } ixDetail(); inPhotos(); });
  box.querySelectorAll('[data-inf]').forEach(b => b.onclick = () => inFile(b.dataset.inf));
}
